<?php declare(strict_types=1);namespace StudPulse\Http;use StudPulse\Database\DB;use StudPulse\Domain\{Input,Access,Notices};use StudPulse\Security\Auth;use StudPulse\Bars\ProviderFactory;final class HomeworkController{public function attach(Auth$a,Request$r,string$id):array{$h=Access::homework($a,$id,true);$m=Access::material($a,Input::id($r->body['materialId']??'')??'');$allowed=$h['group_id']===null?$m['visibility']==='private'&&$m['owner_user_id']===$h['author_user_id']:$m['visibility']==='group'&&$m['group_id']===$h['group_id']&&$m['term_id']===$h['term_id'];if(!$allowed){throw new ApiError(422,'GROUP_MISMATCH','Вложение должно быть доступно той же группе');}DB::run('INSERT IGNORE INTO homework_attachments(homework_id,material_id) VALUES(?,?)',[$id,$m['id']]);return['attached'=>true];}public function list(Auth$a):array{[$limit,$cursor]=Input::page();[$scope,$params]=Access::homeworkScope($a);array_unshift($params,$a->user['id']);$where='';if($cursor){$prior=Access::homework($a,$cursor);$due=$prior['due_at']??'9999-12-31 00:00:00';$where.=" AND (COALESCE(h.due_at,'9999-12-31')>? OR (COALESCE(h.due_at,'9999-12-31')=? AND h.id>?))";array_push($params,$due,$due,$cursor);}if(!empty($_GET['subject'])){Access::subject($a,Input::id($_GET['subject']));$where.=' AND h.subject_id=?';$params[]=$_GET['subject'];}if(isset($_GET['lessonId'])){$where.=' AND h.ruz_lesson_id=?';$params[]=Input::lessonId($_GET['lessonId']);}if(isset($_GET['meetingId'])){$where.=' AND h.linked_meeting_id=?';$params[]=Input::id($_GET['meetingId']);}if(isset($_GET['q'])&&$_GET['q']!==''){$where.=' AND (h.title LIKE ? OR h.description LIKE ?)';$q='%'.Input::text($_GET,'q',100).'%';array_push($params,$q,$q);}if(($_GET['status']??'')==='open'){$where.=' AND hc.user_id IS NULL';}if(($_GET['status']??'')==='completed'){$where.=' AND hc.user_id IS NOT NULL';}$rows=DB::all("SELECT h.*,COALESCE(s.title,h.ruz_subject_title) AS subject_title,u.display_name AS author_name,(hc.user_id IS NOT NULL) AS completed FROM homework h LEFT JOIN subjects s ON s.id=h.subject_id JOIN users u ON u.id=h.author_user_id LEFT JOIN homework_completions hc ON hc.homework_id=h.id AND hc.user_id=? WHERE $scope AND h.deleted_at IS NULL $where ORDER BY COALESCE(h.due_at,'9999-12-31'),h.id LIMIT ".($limit+1),$params);$more=count($rows)>$limit;if($more){array_pop($rows);}return['items'=>$rows,'nextCursor'=>$more?end($rows)['id']:null];}public function detail(Auth$a,string$id):array{$h=Access::homework($a,$id);$h['subject_title']=$h['ruz_subject_title']??($h['subject_id']?DB::one('SELECT title FROM subjects WHERE id=?',[$h['subject_id']])['title']??null:null);$h['comments']=DB::all('SELECT c.id,c.body,c.created_at,c.user_id,u.display_name AS author_name FROM homework_comments c JOIN users u ON u.id=c.user_id WHERE c.homework_id=? AND c.deleted_at IS NULL ORDER BY c.created_at LIMIT 100',[$id]);[$materialScope,$materialParams]=Access::materialReadScope($a);$h['examples']=DB::all("SELECT e.*,u.display_name AS author_name FROM homework_examples e JOIN users u ON u.id=e.uploader_user_id JOIN materials m ON m.id=e.material_id
            WHERE e.homework_id=? AND e.deleted_at IS NULL AND m.deleted_at IS NULL AND $materialScope ORDER BY e.published_at LIMIT 100",[$id,...$materialParams]);$h['attachments']=DB::all("SELECT m.id,m.title FROM homework_attachments ha JOIN materials m ON m.id=ha.material_id
            WHERE ha.homework_id=? AND m.deleted_at IS NULL AND $materialScope",[$id,...$materialParams]);$h['versions']=DB::all('SELECT v.id,v.created_at,u.display_name AS editor_name FROM homework_versions v JOIN users u ON u.id=v.editor_user_id WHERE v.homework_id=? ORDER BY v.created_at DESC LIMIT 20',[$id]);$h['completed']=DB::one('SELECT completed_at FROM homework_completions WHERE homework_id=? AND user_id=?',[$id,$a->user['id']])!==null;return$h;}private function fields(Auth$a,array$b,array$old=[],bool$shared=false):array{$subject=Access::subject($a,Input::id(array_key_exists('subjectId',$b)?$b['subjectId']:($old['subject_id']??null)));$meeting=Access::meeting($a,Input::id(array_key_exists('meetingId',$b)?$b['meetingId']:($old['linked_meeting_id']??null)));if($subject&&$meeting&&$meeting['subject_id']!==$subject['id']){throw new ApiError(422,'SUBJECT_MISMATCH','Занятие относится к другому предмету');}$ruz=[$old['ruz_lesson_id']??null,$old['ruz_lesson_date']??null,$old['ruz_subject_title']??null];if(array_key_exists('lessonId',$b)){$ruz=$b['lessonId']===null?[null,null,null]:$this->ruzLesson($a,$b,$shared);}if($ruz[0]!==null&&($meeting||$subject)){throw new ApiError(422,'SUBJECT_MISMATCH','Выберите одну пару или предмет.');}$title=Input::text($b+['title'=>$old['title']??''],'title');$description=Input::text($b+['description'=>$old['description']??''],'description',20000,false);$dueAt=array_key_exists('dueAt',$b)?Input::date($b['dueAt']):($old['due_at']??null);return[$title,$description,$dueAt,$subject['id']??$meeting['subject_id']??null,$meeting['id']??null,...$ruz];}private function ruzLesson(Auth$a,array$body,bool$shared):array{$id=Input::lessonId($body['lessonId']);$day=Input::day($body['lessonDate']??null);$utc=new \DateTimeZone('UTC');$from=$day->setTimezone($utc)->format('Y-m-d H:i:s');$to=$day->modify('+1 day')->setTimezone($utc)->format('Y-m-d H:i:s');$result=$shared?\StudPulse\Integrations\MpeiSchedule::forGroup($a->group()['canonical_code'],$from,$to):ProviderFactory::make($a)->getMySchedule($from,$to);foreach($result->items as$lesson){if($lesson['id']===$id&&$lesson['source']==='ruz'){return[$id,$day->format('Y-m-d'),mb_substr($lesson['subject_title'],0,240)];}}throw new ApiError(404,'LESSON_NOT_FOUND','Пара не найдена в расписании группы.');}public function create(Auth$a,Request$r):array{$visibility=$r->body['visibility']??($a->membership?'group':'private');if(!in_array($visibility,['group','private'],true)){throw new ApiError(422,'VALIDATION','Выберите видимость задания.');}$m=$visibility==='group'?$a->group():null;$fields=$this->fields($a,$r->body,[],$m!==null);$id=DB::id();DB::run('INSERT INTO homework(id,group_id,term_id,author_user_id,title,description,due_at,subject_id,linked_meeting_id,ruz_lesson_id,ruz_lesson_date,ruz_subject_title) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)',[$id,$m['group_id']??null,$m['term_id']??null,$a->user['id'],...$fields]);Access::audit($a,'homework.create','homework',$id,$r->correlationId);if($m){Notices::group($m,'homework','Новое домашнее задание','homework',$id);}return$this->detail($a,$id);}public function update(Auth$a,Request$r,string$id):array{$old=Access::homework($a,$id,true);$fields=$this->fields($a,$r->body,$old,$old['group_id']!==null);$count=DB::run('UPDATE homework SET title=?,description=?,due_at=?,subject_id=?,linked_meeting_id=?,ruz_lesson_id=?,ruz_lesson_date=?,ruz_subject_title=?,revision=revision+1,updated_at=UTC_TIMESTAMP(6) WHERE id=? AND revision=? AND deleted_at IS NULL',[...$fields,$id,Input::revision($r->body)])->rowCount();if(!$count){throw new ApiError(409,'VERSION_CONFLICT','Задание уже изменено. Ваш текст сохранён в форме.',['currentRevision'=>(int)(DB::one('SELECT revision FROM homework WHERE id=?',[$id])['revision']??0)]);}$new=Access::homework($a,$id);DB::run('INSERT INTO homework_versions(id,homework_id,editor_user_id,old_data,new_data) VALUES(?,?,?,?,?)',[DB::id(),$id,$a->user['id'],json_encode($old,JSON_THROW_ON_ERROR),json_encode($new,JSON_THROW_ON_ERROR)]);if($new['group_id']!==null){Notices::group($a->group(),'homework','Задание обновлено','homework',$id,(int)$new['revision']);}Access::audit($a,'homework.update','homework',$id,$r->correlationId);return$this->detail($a,$id);}public function delete(Auth$a,Request$r,string$id):array{Access::homework($a,$id,true);if(!DB::run('UPDATE homework SET deleted_at=UTC_TIMESTAMP(6),revision=revision+1 WHERE id=? AND revision=?',[$id,Input::revision($r->body)])->rowCount()){throw new ApiError(409,'VERSION_CONFLICT','Задание изменено');}Access::audit($a,'homework.delete','homework',$id,$r->correlationId);return['deleted'=>true];}public function complete(Auth$a,Request$r,string$id):array{Access::homework($a,$id);if(($r->body['completed']??false)===true){DB::run('INSERT IGNORE INTO homework_completions(homework_id,user_id) VALUES(?,?)',[$id,$a->user['id']]);}else{DB::run('DELETE FROM homework_completions WHERE homework_id=? AND user_id=?',[$id,$a->user['id']]);}return['completed'=>($r->body['completed']??false)===true];}public function comment(Auth$a,Request$r,string$id):array{$h=Access::homework($a,$id);$comment=DB::id();DB::run('INSERT INTO homework_comments(id,homework_id,user_id,body) VALUES(?,?,?,?)',[$comment,$id,$a->user['id'],Input::text($r->body,'body',5000)]);if($h['group_id']!==null){Notices::group($a->group(),'comment','Новый комментарий к заданию','homework',$id,(int)hexdec(substr(str_replace('-','',$comment),0,7)));}return['id'=>$comment];}public function example(Auth$a,Request$r,string$id):array{$h=Access::homework($a,$id);$material=Access::material($a,Input::id($r->body['materialId']??'')??'',true);if($h['group_id']===null||$material['visibility']!=='group'||$material['group_id']!==$h['group_id']||$material['term_id']!==$h['term_id']||($r->body['rightsConfirmed']??false)!==true){throw new ApiError(422,'CONFIRM_RIGHTS','Нужен групповой материал и подтверждение права публикации');}$ex=DB::id();DB::run('INSERT INTO homework_examples(id,homework_id,uploader_user_id,material_id,title,description) VALUES(?,?,?,?,?,?)',[$ex,$id,$a->user['id'],$material['id'],Input::text($r->body,'title'),Input::text($r->body,'description',5000,false)]);Notices::group($a->group(),'example','Добавлен пример выполнения','homework',$id,(int)hexdec(substr(str_replace('-','',$ex),0,7)));return['id'=>$ex,'label'=>'Пример пользователя — не проверено преподавателем'];}public function deleteExample(Auth$a,Request$r,string$id,string$example):array{Access::homework($a,$id);$e=DB::one('SELECT * FROM homework_examples WHERE id=? AND homework_id=? AND uploader_user_id=? AND deleted_at IS NULL',[$example,$id,$a->user['id']]);if(!$e){throw new ApiError(404,'NOT_FOUND','Пример не найден');}DB::run('UPDATE homework_examples SET deleted_at=UTC_TIMESTAMP(6) WHERE id=?',[$example]);DB::run('UPDATE materials SET deleted_at=UTC_TIMESTAMP(6) WHERE id=? AND owner_user_id=?',[$e['material_id'],$a->user['id']]);return['deleted'=>true,'materialAccessRevoked'=>true];}}